entries[350034] = { ["name"] = "Fragmentierte Seele", ["text"] = "Unbegrenzte Reichweite\nSofort\nSeelensplitter quälen den betroffenen Spielercharakter, bis sie berührt werden. Die Seelensplitter verursachen alle 1 Sek. 2125 Schattenschaden, verringern die Bewegungsgeschwindigkeit um 20% und verringern den verursachten Schaden und die hervorgerufene Heilung um 30%. Dieser Effekt ist stapelbar." }
